#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Carts;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.Vanilla;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Carts;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Difficulties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;

namespace MVZ2.GameContent.Carts
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.cartCommon)]
    public class CartCommonBehaviour : EntityBehaviourDefinition
    {
        public CartCommonBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.SetCanUpdateBeforeGameStart(true);
            entity.AddBuff<CartFadeInBuff>();
        }

        public override void Update(Entity entity)
        {
            base.Update(entity);
            StateUpdate(entity);
            TriggerChargeUpdate(entity);
            TurnToMoneyUpdate(entity);
        }
        private void StateUpdate(Entity entity)
        {
            var velocity = entity.Velocity;
            switch (entity.State)
            {
                default:
                    if (entity.Position.x < LevelPositions.CART_TARGET_X)
                    {
                        velocity.x = 10;
                    }
                    else
                    {
                        var pos = entity.Position;
                        pos.x = LevelPositions.CART_TARGET_X;
                        entity.Position = pos;
                        velocity.x = 0;
                    }

                    if (entity.Level.EntityExists(e => e.Position.x <= entity.Position.x + TRIGGER_DISTANCE && e.Type == EntityTypes.ENEMY && e.GetLane() == entity.GetLane() && !e.IsDead && !e.IsHarmless() && entity.IsHostile(e)))
                    {
                        entity.TriggerCart();
                    }
                    break;
                case STATE_TRIGGERED:
                    velocity.x = 10;
                    // 获取所有接触到的僵尸。
                    foreach (Entity ent in entity.Level.FindEntities(e => entity.CanCartCrush(e)))
                    {
                        // 碰到小车的僵尸受到伤害。
                        var effects = new DamageEffectList(VanillaDamageEffects.DAMAGE_BOTH_ARMOR_AND_BODY, VanillaDamageEffects.MUTE, VanillaDamageEffects.INSTA_KILL, VanillaDamageEffects.NO_REVIVAL);
                        ent.TakeDamage(VanillaMod.INSTA_DAMAGE_AMOUNT, effects, entity);
                        foreach (var behaviour in entity.Definition.GetBehaviours<ICartBehaviour>())
                        {
                            behaviour.PostCrush(entity, ent);
                        }
                    }
                    // 如果超出屏幕，消失。
                    if (entity.GetBounds().min.x >= LevelPositions.GetBorderX(true))
                    {
                        entity.Remove();
                    }
                    break;
            }
            entity.Velocity = velocity;
        }
        private void TriggerChargeUpdate(Entity entity)
        {
            if (!IsCartTriggerCharging(entity))
            {
                SetCartTriggerCharge(entity, 0);
            }
            SetCartTriggerCharging(entity, false);
            entity.SetModelProperty("Charge", GetCartTriggerCharge(entity) / (float)MAX_TRIGGER_CHARGE);
        }
        private void TurnToMoneyUpdate(Entity entity)
        {
            var timer = entity.GetTurnToMoneyTimer();
            if (timer == null)
                return;
            timer.Run();
            if (timer.Expired)
            {
                var level = entity.Level;
                var difficultyMeta = level.Content.GetDifficultyDefinition(level.Difficulty);
                var money = 50;
                if (difficultyMeta != null)
                {
                    money = difficultyMeta.GetCartConvertMoney();
                }
                var gemEffects = GemEffect.SpawnGemEffects(level, money, entity.Position, entity, true, 0);
                foreach (var effect in gemEffects)
                {
                    effect.PlaySound(VanillaSoundID.points, 1 + (level.GetMaxLaneCount() - entity.GetLane() - 1) * 0.1f);
                }
                level.ShowMoney();
                entity.Remove();
            }
        }
        public static void ChargeUpTrigger(Entity entity)
        {
            SetCartTriggerCharging(entity, true);
            var charge = GetCartTriggerCharge(entity);
            charge++;
            if (charge >= MAX_TRIGGER_CHARGE)
            {
                charge = 0;
                entity.TriggerCart();
            }
            SetCartTriggerCharge(entity, charge);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (!entity.WillRemoveOnDeath(deathInfo))
            {
                entity.CreateFragmentAndPlay(emitSpeed: 500);
            }
            entity.Remove();
        }
        public static void SetCartTriggerCharge(Entity entity, int value) => entity.SetBehaviourField(FIELD_TRIGGER_CHARGE, value);
        public static int GetCartTriggerCharge(Entity entity) => entity.GetBehaviourField<int>(FIELD_TRIGGER_CHARGE);
        public static void SetCartTriggerCharging(Entity entity, bool value) => entity.SetBehaviourField(FIELD_TRIGGER_CHARGING, value);
        public static bool IsCartTriggerCharging(Entity entity) => entity.GetBehaviourField<bool>(FIELD_TRIGGER_CHARGING);

        public static readonly VanillaEntityPropertyMeta<int> FIELD_TRIGGER_CHARGE = new VanillaEntityPropertyMeta<int>("TriggerCharge");
        public static readonly VanillaEntityPropertyMeta<bool> FIELD_TRIGGER_CHARGING = new VanillaEntityPropertyMeta<bool>("TriggerCharging");
        public const float TRIGGER_DISTANCE = 28;
        public const int STATE_TRIGGERED = VanillaCartStates.TRIGGERED;
        public const int MAX_TRIGGER_CHARGE = 30;
    }
}
